<?php
Database::query('DELETE FROM login_limits');
$adminEntry=new HttpClient(); $customerEntry=new HttpClient();
$adminScreen=$adminEntry->requestPath('/admin');
check($adminScreen['code']===200 && str_contains($adminScreen['body'],'<h1>Masuk admin</h1>'),'19 URL admin tanpa slash membuka login khusus');
$adminScreen=$adminEntry->request('admin-login');
check($adminScreen['code']===200 && str_contains($adminScreen['body'],'action="/admin/"') && str_contains($adminScreen['body'],'<base href="/">'),'19 login admin memakai action dan base aset yang benar');
check(!str_contains($adminScreen['body'],'auth-switch') && !str_contains($adminScreen['body'],'Buat akun'),'19 login admin tidak menyediakan registrasi admin publik');
check(str_contains($adminScreen['body'],'type="password" name="password"') && str_contains($adminScreen['body'],'aria-label="Tampilkan password"') && str_contains($adminScreen['body'],'aria-pressed="false"'),'19 password admin tersembunyi dan toggle bertipe button');
check($adminEntry->requestPath('/admin/?page=register')['code']===200 && str_contains($adminEntry->requestPath('/admin/?page=register')['body'],'<h1>Masuk admin</h1>'),'19 query page tidak dapat mengganti role entry admin');
check($adminEntry->request('admin-login','POST',['phone'=>'08170002466','password'=>$password])['code']===419,'19 login admin tanpa CSRF ditolak');
$invalidAdmin=$adminEntry->request('admin-login','POST',['csrf'=>$adminEntry->form('admin-login'),'phone'=>'08170002466','password'=>'wrong-login-test']);
check($invalidAdmin['code']===422 && !str_contains($invalidAdmin['body'],'value="wrong-login-test"'),'19 password admin salah ditolak dan tidak dipantulkan');
check($adminEntry->login('+6281822233344',$password,true)['code']===422 && $adminEntry->request('dashboard')['code']===303,'19 akun pelanggan tidak bisa login sebagai admin');
check($customerEntry->login('08170002466',$password)['code']===422 && $customerEntry->request('dashboard')['code']===303,'19 akun admin tidak bisa login melalui formulir pelanggan');
Database::query('DELETE FROM login_limits');
$forgedAdmin=$adminEntry->request('admin-login','POST',['csrf'=>$adminEntry->form('admin-login'),'phone'=>'081822233344','password'=>$password,'role'=>'admin']);
check($forgedAdmin['code']===422 && $adminEntry->request('customers')['code']===303,'19 role POST tidak dapat mengubah akun pelanggan menjadi admin');
$successAdmin=$adminEntry->login('08170002466',$password,true);
check($successAdmin['code']===303 && str_contains($successAdmin['headers'],'Location: /index.php?page=dashboard') && $adminEntry->request('dashboard')['code']===200,'19 admin masuk lewat admin dan redirect ke root aplikasi');
$adminExit=$adminEntry->request('logout','POST',['csrf'=>$adminEntry->form('dashboard')]);
check($adminExit['code']===303 && str_contains($adminExit['headers'],'Location: /admin/') && $adminEntry->request('dashboard')['code']===303,'19 logout admin mengakhiri sesi dan kembali ke admin');
$guestAdminEndpoint=$adminEntry->request('customers');
check($guestAdminEndpoint['code']===303 && str_contains($guestAdminEndpoint['headers'],'Location: /admin/'),'19 endpoint admin mengarahkan tamu ke login admin');
check($customerEntry->login('081822233344',$password)['code']===303 && $customerEntry->request('dashboard')['code']===200,'19 login pelanggan tetap berfungsi di URL semula');
$customerExit=$customerEntry->request('logout','POST',['csrf'=>$customerEntry->form('dashboard')]);
check($customerExit['code']===303 && str_contains($customerExit['headers'],'page=login'),'19 logout pelanggan kembali ke login pelanggan');
$registerScreen=$customerEntry->request('register');
check(substr_count($registerScreen['body'],'data-password-toggle')===2 && substr_count($registerScreen['body'],'type="password"')===2 && substr_count($registerScreen['body'],'aria-pressed="false"')===2,'19 registrasi memiliki dua toggle mandiri dengan default tersembunyi');
check($adminEntry->requestPath('/assets/icons/mdi/eye-outline.svg')['code']===200 && $adminEntry->requestPath('/assets/icons/mdi/eye-off-outline.svg')['code']===200,'19 kedua ikon mata MDI lokal tersedia');
Database::query('DELETE FROM login_limits');
